// Entry point of the Cloudflare Worker: the OpenNext build of the site plus
// the scheduled jobs Vercel used to run (see "triggers" in wrangler.jsonc).
// A schedule calls the same route Vercel's cron called; a failed job throws,
// so it shows up as an error in the Worker's logs.
// Generated by `opennextjs-cloudflare build`.
import handler from "../.open-next/worker.js";

const JOBS = {
  "0 2 * * *": "/api/cron/translate",
  "0 14 * * *": "/api/health",
};

const worker = {
  fetch: handler.fetch,

  async scheduled(controller, env, ctx) {
    const path = JOBS[controller.cron];
    if (!path) {
      throw new Error(`No job for schedule "${controller.cron}"`);
    }
    const headers = new Headers();
    if (path.startsWith("/api/cron/") && env.CRON_SECRET) {
      headers.set("authorization", `Bearer ${env.CRON_SECRET}`);
    }
    const response = await handler.fetch(
      new Request(new URL(path, "https://scheduled.invalid"), { headers }),
      env,
      ctx,
    );
    const body = (await response.text()).slice(0, 500);
    console.log(`${controller.cron} ${path} -> ${response.status} ${body}`);
    if (!response.ok) {
      throw new Error(`${path} answered ${response.status}`);
    }
  },
};

export default worker;
